document.addEventListener('click',e=>{let kt=e.target.closest&&e.target.closest('.kdT');if(kt){KD.on=!KD.on;kdSave();kdRe();return}let sd=e.target.closest&&e.target.closest('.sosD');if(sd){scPos=sd.dataset.pos;document.querySelectorAll('.scPos').forEach(x=>x.classList.toggle('on',x.dataset.v===scPos));renderSchedule();showView('insights');showInsight('schedule');return}if(e.target.id==='profTrade'&&curPlayer)openTrade('quick',curPlayer.id);if(e.target.id==='profCopy'&&curPlayer)fmCopyLink(curPlayer)});function fmSlug(n){return String(n||'').normalize('NFKD').replace(/[^\x00-\x7f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'')||'player'}var fmSlugs=null;function fmSlugOf(id){if(!fmSlugs){fmSlugs={};var used={},add=function(x,pos){if(!x||fmSlugs[x.id])return;var s=fmSlug(x.name);if(used[s])s=s+'-'+fmSlug(x.team||pos);used[s]=1;fmSlugs[x.id]=s};DB.forEach(function(x){add(x,x.pos)});(META.qbs||[]).forEach(function(x){add(x,'QB')});var kd=META.kd||{};(kd.k||[]).concat(kd.d||[]).forEach(function(x){add(x,x.pos)})}return fmSlugs[id]}function fmCopyLink(p){var s=fmSlugOf(p.id),b=document.getElementById('profileBody'),lt=b&&b.querySelector('.ptile[data-k="log"]'),onLog=lt&&b.dataset.pf&&b.dataset.pf===lt.dataset.pfg;var u=s?'https://fantasymania.org/players/'+s+'/'+(onLog?'game-log/':''):location.origin+'/#p='+p.id;var done=function(){try{toast(onLog?'Game log link copied':'Link copied')}catch(e){}};if(navigator.share&&matchMedia('(pointer:coarse)').matches){navigator.share({title:p.name+(onLog?' game log':'')+' | Fantasy Mania',url:u}).catch(function(){});return}if(navigator.clipboard)navigator.clipboard.writeText(u).then(done,function(){prompt('Copy this link',u)});else prompt('Copy this link',u)}
