 var rk={};cols.forEach(function(c){var o=all.slice().filter(function(r){return r[c.sx]!=null}).sort(function(a,b){return (c.hi?b[c.sx]-a[c.sx]:a[c.sx]-b[c.sx])||b[4]-a[4]});var m={};o.forEach(function(r,i){m[r[0]]=i/Math.max(1,o.length-1)});rk[c.k]=m});
 var rows=all.filter(function(r){return r[col.sx]!=null});if(g==='rec'&&ADVST.p!=='ALL')rows=rows.filter(function(r){return r[3]===ADVST.p});
 var bestFirst=ADVST.dir==='best',dir=(bestFirst===col.hi)?-1:1;rows.sort(function(a,b){return dir*(a[col.sx]-b[col.sx])||b[4]-a[4]});
 var min=XTRA.min||[14,24],adjd=col.k!=='tgt'&&col.k!=='car';
 document.getElementById('advNote').innerHTML='Sorted by <b>'+col.t+'</b>, '+(bestFirst?'best':'worst')+' first. Tap a column title to sort, tap it again to flip it. '+(g==='rec'?'Receivers with at least '+min[0]+' targets.':'Running backs with at least '+min[1]+' carries.')+(adjd?' Rates are adjusted for volume, so 1 target with 0 drops cannot beat 100 targets with 0 drops.':'');
