(function(){var F=XTRA.ftn||{},body=document.getElementById('styBody');if(!body)return;var teams=Object.keys(F);if(!teams.length){body.innerHTML='<p class="dcNote">Charting data is not available yet.</p>';return}
 var COLS=[['pa','Play-action','% of pass plays that use a play fake',1],['sc','Screens','% of pass plays that are screens',1],['mo','Motion','% of plays with pre-snap motion',1],['nh','No-huddle','% of plays run without a huddle',1],['rpo','RPO','% of plays that are run-pass options',1],['pr','Pass rate','% of plays that are passes',1],['bl','Blitzed','% of dropbacks where the defense sent extra rushers',1],['dbl','Blitzes','How often this defense blitzes',1]],sk='pa',sd=-1;
 function draw(){var rows=teams.slice().sort(function(a,b){return sd*((F[a][sk]||0)-(F[b][sk]||0))});
  var mx={};COLS.forEach(function(c){mx[c[0]]=Math.max.apply(null,teams.map(function(t){return F[t][c[0]]||0}))||1});
  var top=rows[0],c0=COLS.filter(function(c){return c[0]===sk})[0];
  body.innerHTML='<p class="dcNote" style="margin-top:0"><b>'+c0[1]+':</b> '+c0[2]+'. Highest is '+(sd<0?top:rows[rows.length-1])+' ('+(F[sd<0?top:rows[rows.length-1]][sk]||0)+'%).</p><div class="styWrap"><table class="styT"><thead><tr><th>Team</th>'+COLS.map(function(c){return '<th class="'+(c[0]===sk?'on':'')+'" data-k="'+c[0]+'">'+c[1]+(c[0]===sk?(sd<0?' &#9660;':' &#9650;'):'')+'</th>'}).join('')+'</tr></thead><tbody>'+rows.map(function(t){return '<tr><td><span class="styTm">'+tlogo(t,'sm')+t+'</span></td>'+COLS.map(function(c){var v=F[t][c[0]];return '<td class="'+(c[0]===sk?'on':'')+'">'+(v==null?'&mdash;':v.toFixed(0)+'%')+'<i style="width:'+Math.round(100*(v||0)/mx[c[0]])+'%"></i></td>'}).join('')+'</tr>'}).join('')+'</tbody></table></div><p class="dcNote">Offense columns: Play-action through Pass rate, plus how often the offense gets blitzed. "Blitzes" is how often that team&#39;s defense sends extra rushers. Charting by FTN through nflverse.</p>';
  body.querySelectorAll('th[data-k]').forEach(function(h){h.onclick=function(){if(sk===h.dataset.k)sd=-sd;else{sk=h.dataset.k;sd=-1}draw()}})}
 draw()})();
