var QBW={'Production':35,'Passing':15,'Rushing':12,'Scoring':13,'Efficiency':25};
Object.assign(QHELP,{'Production':'Fantasy points per game (PPR) against other quarterbacks. The biggest single piece, because points are what you start him for.','Passing':'60% passing yards per game, 40% attempts per game. More throws and more yards mean a safer floor.','Rushing':'65% rushing yards per game, 35% rushing touchdowns per game. Quarterbacks who run get a big fantasy boost.','Scoring':'60% passing touchdowns per game, 40% how often his throws turn into touchdowns.','Efficiency':'How well he actually plays, not just how much: 35% scoring impact (points he adds per throw), 20% accuracy, 15% yards per throw, 15% few interceptions, 15% few sacks.'});
var QBSC='starters';try{QBSC=localStorage.getItem('fm_qbsc')==='all'?'all':'starters'}catch(e){}
var _QS=null;
function qbStart(){if(_QS)return _QS;_QS={};var by={},T=(typeof DEPTH!=='undefined'&&DEPTH&&DEPTH.teams)||{};(META.qbs||[]).forEach(function(x){(by[x.team]=by[x.team]||[]).push(x)});
 Object.keys(by).forEach(function(t){var L=by[t],tot=L.reduce(function(a,x){return a+((x.qa&&x.qa.db)||0)},0),d1=null,o=(T[t]&&T[t].off)||[];o.forEach(function(r){if(r[0]==='QB'&&r[3]&&r[3][0])d1=r[3][0][1]});
  L.forEach(function(x){var sh=tot?((x.qa&&x.qa.db)||0)/tot:0;if(x.id===d1||sh>=.5)_QS[x.id]=1})});
 return _QS}
function qbQ(all){var L=(META.qbs||[]).filter(function(x){return x.qual!==false&&x.mania!=null&&x.m});if(all||QBSC==='all')return L;var S=qbStart();return L.filter(function(x){return S[x.id]})}
function qbIsStarter(p){return !!qbStart()[p.id]}
var QBMET=[
 {k:'ppr',l:'PPR points per game',g:function(q){return q.m.ppr},d:1,hi:1},
 {k:'pyd',l:'Passing yards per game',g:function(q){return q.m.pyd},d:0,hi:1},
 {k:'ptd',l:'Passing TDs per game',g:function(q){return q.m.ptd},d:1,hi:1},
 {k:'int',l:'Interceptions per game',g:function(q){return q.m.int},d:1,hi:0},
 {k:'cmp',l:'Completion rate',g:function(q){return q.m.cmp},d:1,hi:1,sf:'%'},
 {k:'ypa',l:'Yards per attempt',g:function(q){return q.m.ypa},d:1,hi:1},
 {k:'ruy',l:'Rushing yards per game',g:function(q){return q.m.ruy},d:0,hi:1},
 {k:'rtd',l:'Rushing TDs per game',g:function(q){return q.m.rtd},d:2,hi:1}];
var QBADV=[
 {k:'epa',l:'Scoring impact',tech:'EPA per dropback',g:function(q){return q.qa&&q.qa.epa},d:2,hi:1,sg:1,unit:'points added per throw',help:'How many points his offense gains every time he drops back to pass, compared with a normal play. The best single measure of how much a QB helps his team score.'},
 {k:'cpoe',l:'Accuracy',tech:'Completion % over expected',g:function(q){return q.qa&&q.qa.cpoe},d:1,hi:1,sg:1,sf:'%',unit:'completions beyond what is expected',help:'His completion rate compared with what an average QB would complete on the same throws. A hard throw counts for more, so he is not punished for tough passes.'},
 {k:'skr',l:'Avoids sacks',tech:'Sack rate',g:function(q){return q.qa&&q.qa.skr},d:1,hi:0,sf:'%',unit:'of dropbacks end in a sack',help:'How often he gets sacked. Lower is better. It is partly the offensive line and partly how quickly he gets rid of the ball.'},
 {k:'badt',l:'Bad throws',tech:'Off-target rate',g:function(q){return q.qa&&q.qa.badt},d:1,hi:0,sf:'%',unit:'of throws miss the target',help:'How often his throws are charted as off target, not counting throwaways. Lower is better.'},
 {k:'aya',l:'Throw depth',tech:'Air yards per throw',g:function(q){return q.qa&&q.qa.aya},d:1,hi:1,neutral:1,unit:'yards, on average, the ball travels',help:'How far downfield he throws. This is style, not quality. Deep throwers have bigger highs and lows. Short throwers are steadier.',tags:['Short passer','Mixed','Deep passer']},
 {k:'pres',l:'Pressure he faces',tech:'Pressure rate',g:function(q){return q.qa&&q.qa.pres},d:1,hi:0,neutral:1,sf:'%',unit:'of dropbacks are pressured',help:'How often defenders get to him. That is mostly his offensive line, so this is context and not a grade on him.',tags:['Busy pocket','Normal','Clean pocket']}];
var QBX={att:{k:'att',l:'Attempts',g:function(q){return q.m.att},d:1,hi:1},tdr:{k:'tdr',l:'TD rate',g:function(q){return q.m.att?100*q.m.ptd/q.m.att:NaN},d:1,hi:1,sf:'%'},intr:{k:'intr',l:'Interceptions',g:function(q){return q.m.att?100*q.m.int/q.m.att:NaN},d:1,hi:0,sf:'%'}};
var QBSUB={'Production':['ppr'],'Passing':['pyd','att'],'Rushing':['ruy','rtd'],'Scoring':['ptd','tdr'],'Efficiency':['epa','cpoe','ypa','intr','skr']};
