function qbPanels(p){var st=qbStoryHTML(p),n=qbNums(p),a=qbAdvHTML(p),l=qbLadder(p);var cs=qbCastHTML(p);return (st?'<div class="panel qbStory">'+st+'</div>':'')+(cs?'<div class="panel qbCastP">'+cs+'</div>':'')+(n?'<div class="panel qbNums">'+n+'</div>':'')+(a?'<div class="panel advPanel qbAdv">'+a+'</div>':'')+(l?'<div class="panel qbLad">'+l+'</div>':'')}
