 if(k==='qb'){if(p.mania==null)return '<div class="pvs">Not rated yet.</div>';return pvRow('Mania Rating',Number(p.mania).toFixed(1),grade(p.mania))+(p.pos_rank?pvRow('Quarterback rank','QB'+p.pos_rank+' of '+qbQ(true).length):'')+'<div class="pvs">Open to see how it is built</div>'}
