  var ros=R[0],usr=R[1],P=R[2],ours=Object.values(trCtx().V).map(function(v){return v.p}),idx={};
  ours.forEach(function(p){(idx[trEspnKey(p.name)]=idx[trEspnKey(p.name)]||[]).push(p)});
