   (r.players||[]).forEach(function(sid){var s=P[sid];if(!s)return;if(/^(K|DEF)$/.test(s.position||'')){var kq=kdSl(s,sid);if(kq){smap[sid]=kq;if(ids.indexOf(kq)<0)ids.push(kq)}return}if(!/^(QB|RB|WR|TE)$/.test(s.position||''))return;var c=idx[trEspnKey(s.full_name||((s.first_name||'')+' '+(s.last_name||'')))]||[],p=c.find(function(x){return x.pos===s.position})||c[0];if(p){smap[sid]=p.id;if(ids.indexOf(p.id)<0)ids.push(p.id)}else miss.push(s.full_name)});
