/* ===== v185 kickers and defenses: real points everywhere ===== */
var KDX=(META&&META.kd)||{k:[],d:[],scoring:null},KDR={},KDPm={},KDG=null;
(KDX.k||[]).concat(KDX.d||[]).forEach(function(r){KDR[r.id]=r});
