function kdLogo(t){var L=(XTRA&&XTRA.logos||{})[t];return L?L.l:''}
function kdPl(id){if(!KDR)return null;var r=KDR[id];if(!r)return null;if(KDPm[id])return KDPm[id];
 var p={id:r.id,name:r.name,team:r.team,pos:r.pos,headshot:r.pos==='DST'?kdLogo(r.team):(r.headshot||''),kd:1,r:r,games:r.games,mania:r.rating,m:{ppr:r.ppg},logs:[],flags:[],bl:[],opp:r.opp||null,out:false,inj:null,start:r.wkr,proj:r.wk==null?null:{pts:r.wk},rank:r.rank,pos_rank:r.rank,team_rank:null,depth:null,played:null,qual:true,traded:false};
 KDPm[id]=p;return p}
